// Üretilen dosya: tool/ozgun/uret.py. Ekonomi ve Finans · Temel muhasebe ve finansal tablo analizi: bilanço eşitliği, gelir tablosu, cari oran, kârlılık marjları, amortisman ve başabaş noktası (zor).
const ozEconomics18Zor = <(String, String, List<String>, String)>[
  ('Maliyeti 40.000 TL olan ticari malı müşterisine 55.000 TL\'ye peşin satan bir işletmenin temel muhasebe eşitliğinde gerçekleşen net değişim nedir?', 'Varlıklar net 15.000 TL artar, özkaynaklar 15.000 TL artar', ['Varlıklar net 55.000 TL artar, yabancı kaynaklar 40.000 TL artar', 'Varlıkların toplamı değişmez, yalnızca stok azalıp kasa artar', 'Varlıklar net 40.000 TL azalır, özkaynaklar 55.000 TL artar'], 'Kasaya 55.000 TL girer, stoktan 40.000 TL çıkar (varlıklarda net +15.000 TL); aradaki 15.000 TL\'lik kâr ise özkaynakları artırır.'),
  ('Bir işletme, vadesi gelen 120.000 TL\'lik kısa vadeli banka kredisini, başka bir bankadan çektiği 3 yıl vadeli yeni bir krediyle kapattığında bilançoda ne olur?', 'Aktif toplamı değişmez; kısa vadeli yabancı kaynaklar azalırken uzun vadeli yabancı kaynaklar artar', ['Aktif ve pasif toplamı 120.000 TL azalır; özkaynaklar aynı tutarda artış gösterir', 'Dönen varlıklar 120.000 TL artarken uzun vadeli yabancı kaynaklar 120.000 TL azalır', 'Pasif toplamı 240.000 TL artarken aktif toplamı 120.000 TL artış gösterir'], 'İşlem yalnızca borcun vade yapısını değiştirir: kısa vadeli mali borç kapanırken uzun vadeli mali borç doğar, bilanço toplamı sabit kalır.'),
  ('Dönem başında varlıkları 500.000 TL ve borçları 200.000 TL olan bir işletmenin, dönem sonunda varlıkları 680.000 TL ve borçları 250.000 TL olmuştur. Dönem içinde sermaye artırımı veya kâr dağıtımı yapılmadığına göre işletmenin dönem net sonucu nedir?', '130.000 TL kâr', ['180.000 TL kâr', '50.000 TL zarar', '130.000 TL zarar'], 'Dönem başı özkaynak = 500.000 - 200.000 = 300.000 TL; dönem sonu özkaynak = 680.000 - 250.000 = 430.000 TL\'dir. Özkaynaklardaki 130.000 TL\'lik artış dönem net kârıdır.'),
  ('Yıl başında özkaynakları 400.000 TL olan bir şirkete ortaklar yıl içinde 70.000 TL yeni sermaye koymuş ve şirket yıl sonunda ortaklara 30.000 TL kâr payı (temettü) dağıtmıştır. Yıl sonu özkaynakları 510.000 TL ise şirketin o yıl elde ettiği net kâr kaç TL\'dir?', '70.000 TL', ['110.000 TL', '150.000 TL', '40.000 TL'], 'Dönem sonu özkaynak = Dönem başı özkaynak + Ek sermaye - Temettü + Net Kâr formülünden: 510.000 = 400.000 + 70.000 - 30.000 + Net Kâr => 510.000 = 440.000 + Net Kâr => Net Kâr = 70.000 TL.'),
  ('Bir işletmenin uzun vadeli kredisinin bu yıl ödenecek taksitini kısa vadeli borçlara aktarmayı unutması finansal analizde hangi yanıltıcı sonuca yol açar?', 'İşletmenin kısa vadeli borç ödeme gücünün (likiditesinin) gerçekte olduğundan daha yüksek görünmesine', ['İşletmenin toplam yabancı kaynak tutarının gerçekte olduğundan daha düşük hesaplanmasına', 'İşletmenin özkaynak kârlılığının ve net dönem kârının olduğundan daha fazla görünmesine', 'İşletmenin toplam aktif büyüklüğünün pasif büyüklüğünden daha fazla çıkmasına'], 'Toplam borç değişmese de kısa vadeli borçlar eksik görüneceği için cari oran ve net işletme sermayesi yapay biçimde yüksek ve olumlu algılanır.'),
  ('Bir işletmede net işletme sermayesinin negatif çıkması (Dönen Varlıklar < Kısa Vadeli Yabancı Kaynaklar) aşağıdakilerden hangisinin kesin göstergesidir?', 'Duran varlıkların bir kısmının kısa vadeli borçlarla finanse edildiğinin', ['İşletmenin toplam borçlarının toplam varlıklarını aştığının', 'İşletmenin son faaliyet döneminde ticari zarar elde ettiğinin', 'Uzun vadeli yabancı kaynakların özkaynaklardan daha büyük olduğunun'], 'Aktif = Pasif olduğundan, Dönen Varlıklar < Kısa Vadeli Borçlar ise zorunlu olarak Duran Varlıklar > (Uzun Vadeli Borçlar + Özkaynaklar) olur; yani duran varlıkların bir bölümü kısa vadeli kaynakla finanse edilmiştir.'),
  ('Brüt alış değeri 200.000 TL olan bir makine için bugüne kadar toplam 80.000 TL birikmiş amortisman ayrılmıştır. Bu makinenin bilançodaki net defter değeri kaç TL\'dir ve boş araziler için neden amortisman ayrılmaz?', '120.000 TL; boş arazilerin sınırsız ekonomik ömre sahip olduğu kabul edildiği için', ['280.000 TL; boş arazilerin piyasa değeri her yıl düzenli olarak düştüğü için', '120.000 TL; boş araziler dönen varlıklar grubunda ticari mal olarak izlendiği için', '200.000 TL; boş arazilerin alım satımı vergiden tamamen muaf tutulduğu için'], 'Net defter değeri = Maliyet (200.000) - Birikmiş Amortisman (80.000) = 120.000 TL\'dir. Boş araziler yıpranmadığı ve ekonomik ömrü sonsuz sayıldığı için amortismana tabi tutulmaz.'),
  ('"Geçmiş yıllar kârları 5.000.000 TL olan bir şirketin bankasında mutlaka en az 5.000.000 TL nakit para vardır." iddiası muhasebe ilkeleri açısından neden yanlıştır?', 'Kâr bir kaynak (özkaynak) kalemidir; bu kaynakla çoktan makine, stok alınmış veya borç ödenmiş olabilir', ['Geçmiş yıllar kârları yalnızca yabancı para cinsinden merkez bankasında bloke olarak tutulmak zorundadır', 'Kâr rakamı bilançonun pasifinde değil, yalnızca gelir tablosunun dipnotlarında izlenen bir bilgidir', 'Muhasebe kurallarına göre elde edilen kârın tamamı ertesi yıl vergi dairesine devredilmek zorundadır'], 'Pasifteki özkaynak kalemleri fonun nereden geldiğini gösterir; bu fonun aktifte nakitte mi yoksa fabrika/stok gibi varlıklarda mı durduğu bilançonun aktif yapısına bağlıdır.'),
  ('Bir işletmenin toplam yabancı kaynaklarının toplam varlıklarını aşması (Yabancı Kaynaklar > Varlıklar) durumunda bilançoda nasıl bir tablo ortaya çıkar?', 'Özkaynaklar toplamı negatif olur', ['Aktif toplamı pasif toplamından daha küçük bir sayıya düşer', 'Duran varlıklar kendiliğinden dönen varlıklar grubuna dönüşür', 'Temel muhasebe eşitliği bozulur ve bilanço denkleştirilemez'], 'Bilanço eşitliği (Varlıklar = Borçlar + Özkaynaklar) her zaman korunur; borçlar varlıkları aşarsa aradaki fark negatif özkaynak (büyük zararlar nedeniyle sermayenin erimesi) olarak pasifte yer alır ve eşitlik sürer.'),
  ('Bir üretim işletmesinin bilançosunda yer alan "İlk Madde ve Malzeme", "Yarı Mamuller" ve "Mamuller" hesaplarının ortak özelliği nedir?', 'Üçünün de Dönen Varlıklar içindeki "Stoklar" grubunda yer alması', ['Üçünün de Duran Varlıklar içindeki "Maddi Duran Varlıklar" grubunda izlenmesi', 'Üçünün de amortismana tabi tutularak yıllar içinde giderleştirilmesi', 'Üçünün de pasifte "Kısa Vadeli Yabancı Kaynaklar" altında sınıflandırılması'], 'Hammadde, üretim aşamasındaki yarı mamul ve tamamlanmış mamul, normal faaliyet döngüsü içinde satılıp nakde dönüşeceği için dönen varlıklarda "Stoklar" grubunda yer alır.'),
  ('Bir anonim şirketin, daha önce elde edip "Kâr Yedekleri" hesabında biriktirdiği 250.000 TL\'yi bedelsiz sermaye artırımı yoluyla "Ödenmiş Sermaye" hesabına aktarması bilançoyu nasıl etkiler?', 'Özkaynaklar toplamı ve bilanço büyüklüğü değişmez; yalnızca özkaynak içi kalemler yer değiştirir', ['Şirketin kasa veya banka hesabına 250.000 TL taze nakit girişi olur ve özkaynaklar büyür', 'Uzun vadeli yabancı kaynaklar 250.000 TL azalırken özkaynaklar 250.000 TL artar', 'Dönen varlıklar 250.000 TL azalırken maddi duran varlıklar 250.000 TL artış gösterir'], 'Bedelsiz sermaye artırımında dışarıdan nakit gelmez; özkaynaklar içindeki kâr yedekleri azalırken ödenmiş sermaye artar, toplam özkaynak sabit kalır.'),
  ('Bir şirketin tahvil ihraç ederek yatırımcılardan 5 yıl vadeli borç para toplaması ile yeni hisse senedi ihraç ederek ortak alması arasındaki bilanço farkı nedir?', 'Tahvil ihracı "Uzun Vadeli Yabancı Kaynakları", hisse senedi ihracı ise "Özkaynakları" artırır', ['Tahvil ihracı "Özkaynakları", hisse senedi ihracı ise "Kısa Vadeli Yabancı Kaynakları" artırır', 'Tahvil ihracı bilançonun aktifini azaltırken, hisse senedi ihracı aktifi değiştirmez', 'Her iki işlem de bilançoda "Ticari Borçlar" grubunda aynı hesap altında raporlanır'], 'Tahvil bir borçlanma aracıdır ve vadesi 1 yılı aştığı için uzun vadeli mali borç yaratır; hisse senedi ise mülkiyet payıdır ve ödenmiş sermayeyi (özkaynakları) büyütür.'),
  ('Yeni kurulan bir anonim şirkette ortaklar 1.000.000 TL sermaye taahhüt etmiş, kuruluş anında bunun 400.000 TL\'sini şirket bankasına yatırmış, kalan 600.000 TL\'yi ise daha sonra ödeyeceklerini beyan etmişlerdir. Kuruluş bilançosunda özkaynak (ödenmiş sermaye) kaç TL görünür?', '400.000 TL', ['1.000.000 TL', '600.000 TL', '1.400.000 TL'], 'Sermaye (1.000.000 TL) hesabından, henüz yerine getirilmemiş taahhütleri gösteren "Ödenmemiş Sermaye (-)" (600.000 TL) düşülür; bilançoda ödenmiş sermaye ve özkaynak 400.000 TL, bankalar 400.000 TL olur.'),
  ('Cari oranı 2,0 olan ve kısa vadeli yabancı kaynakları 180.000 TL olan bir işletme, satıcılara olan 60.000 TL\'lik borcunu kasadaki nakitle öderse yeni cari oranı kaç olur?', '2,5', ['2,0', '1,5', '3,0'], 'Başlangıçta Dönen Varlıklar = 2,0 × 180.000 = 360.000 TL\'dir. Ödeme sonrası Dönen Varlıklar = 360.000 - 60.000 = 300.000 TL, Kısa Vadeli Borçlar = 180.000 - 60.000 = 120.000 TL olur. Yeni cari oran = 300.000 / 120.000 = 2,5\'tir.'),
  ('Toplam yabancı kaynakların toplam varlıklara oranını ifade eden "Finansal Kaldıraç (Borçluluk) Oranı" %40 olan bir işletmenin toplam varlıkları 2.000.000 TL ise özkaynakları kaç TL\'dir?', '1.200.000 TL', ['800.000 TL', '1.600.000 TL', '500.000 TL'], 'Yabancı Kaynaklar = 2.000.000 × 0,40 = 800.000 TL\'dir. Temel muhasebe eşitliğinden Özkaynaklar = 2.000.000 - 800.000 = 1.200.000 TL bulunur.'),
  ('Bir işletmenin bilançosunda aktif toplamı çok büyük olmasına rağmen işletmenin vadesi gelen elektrik faturasını ve maaşları ödeyememesi (teknik ödeme güçlüğü) en iyi hangi bilanço dengesizliğiyle açıklanır?', 'Varlıkların büyük bölümünün likiditesi düşük duran varlıklarda toplanması ve hazır değerlerin yetersiz kalması', ['Özkaynakların toplam pasif içindeki payının yabancı kaynaklardan daha yüksek olması', 'İşletmenin geçmiş yıllarda hiç amortisman ayırmamış ve yedek akçe biriktirmemiş olması', 'Bilançonun aktif toplamının pasif toplamından daha büyük hesaplanmış olması'], 'Varlık büyüklüğü tek başına nakit gücü demek değildir; varlıklar bina ve arazi gibi likit olmayan duran varlıklara bağlanmışsa işletme nakit sıkışıklığına düşebilir.'),
  ('Aylık kapasitesi 10.000 adet olan bir fabrikada 6.000 adet üretimde toplam maliyet 420.000 TL, 9.000 adet üretimde toplam maliyet 555.000 TL ise aylık sabit maliyet kaç TL\'dir?', '150.000 TL', ['135.000 TL', '180.000 TL', '270.000 TL'], 'Birim değişken maliyet = (555.000 - 420.000) / (9.000 - 6.000) = 135.000 / 3.000 = 45 TL; Sabit maliyet = 420.000 - (6.000 x 45) = 150.000 TL.'),
  ('Başabaş noktası 4.000 adet olan ve hâlihazırda 5.000 adet satış yapan bir işletmenin güvenlik marjı (emniyet payı) oranı yüzde kaçtır?', '%20', ['%25', '%80', '%15'], 'Güvenlik marjı miktarı = 5.000 - 4.000 = 1.000 adet; Güvenlik marjı oranı = 1.000 / 5.000 = %20\'dir.'),
  ('Maliyeti 400.000 TL ve ekonomik ömrü 5 yıl olan bir tesisat için azalan bakiyeler (hızlandırılmış) amortisman yöntemi (normal oranın iki katı) uygulandığında ikinci yılın amortisman gideri kaç TL olur?', '96.000 TL', ['160.000 TL', '80.000 TL', '64.000 TL'], 'Normal oran %20, azalan bakiyeler oranı %40\'tır. 1. yıl gideri = 400.000 x 0,40 = 160.000 TL; kalan net değer 240.000 TL; 2. yıl gideri = 240.000 x 0,40 = 96.000 TL.'),
  ('Yeni bir otomasyon yatırımıyla aylık sabit maliyetlerini 100.000 TL artırıp birim değişken maliyetini 25 TL düşürmeyi planlayan bir fabrika, satış fiyatını sabit tutarsa hangi üretim düzeyinin üzerinde bu yatırımdan kârlı çıkar?', '4.000 adedin üzerindeki üretim düzeylerinde', ['2.500 adedin altındaki üretim düzeylerinde', 'Tam olarak 1.000 adetlik üretim hacminde', 'Üretim miktarından bağımsız her düzeyde'], 'Maliyet kayıtsızlık noktası: Ek sabit maliyet / Birim değişken maliyet tasarrufu = 100.000 / 25 = 4.000 adet; bunun üzerinde otomasyon daha düşük toplam maliyet sağlar.'),
  ('Vergi oranı %20 olan bir işletmede sabit maliyetler 220.000 TL, birim satış fiyatı 150 TL ve birim değişken maliyet 95 TL\'dir. Vergi sonrası 88.000 TL net kâr elde etmek için kaç adet satış yapılmalıdır?', '6.000 adet', ['5.600 adet', '6.400 adet', '5.280 adet'], 'Vergi öncesi hedef kâr = 88.000 / (1 - 0,20) = 110.000 TL; Birim katkı payı = 150 - 95 = 55 TL; Gerekli miktar = (220.000 + 110.000) / 55 = 6.000 adet.'),
  ('Faaliyet kaldıracı derecesi (toplam katkı payı / faaliyet kârı) 4 olarak hesaplanan bir işletmede satış hacmi %10 arttığında esas faaliyet kârı yüzde kaç artar?', '%40', ['%14', '%25', '%4'], 'Faaliyet kaldıracı derecesi, satışlardaki yüzdesel değişimin faaliyet kârını kaç kat etkileyeceğini gösterir: 4 x %10 = %40 artış sağlar.'),
  ('Hammadde birim fiyatlarının sürekli düştüğü deflasyonist bir piyasada, dönem kârını vergi planlaması amacıyla daha düşük raporlamak isteyen bir işletme FIFO ile ağırlıklı ortalama yöntemlerinden hangisini tercih etmelidir?', 'İlk Giren İlk Çıkar (FIFO) yöntemini', ['Ağırlıklı ortalama maliyet yöntemini', 'Son alınan partiyle değerleme yöntemini', 'Piyasa satış fiyatıyla değerleme yöntemini'], 'Fiyatlar düşerken en eski stoklar en pahalı olanlardır; FIFO bu pahalı stokları satılan malın maliyetine yazarak SMM\'yi büyütür ve kârı düşük gösterir.'),
  ('İki ürün satan bir mağazada A ürününün birim katkı payı 40 TL, B ürününün birim katkı payı 80 TL\'dir. Satışların %75\'i A, %25\'i B ürününden oluşuyorsa ve toplam sabit maliyet 250.000 TL ise toplam başabaş satış miktarı kaç adettir?', '5.000 adet', ['4.167 adet', '6.250 adet', '3.125 adet'], 'Ağırlıklı ortalama birim katkı payı = (40 x 0,75) + (80 x 0,25) = 30 + 20 = 50 TL; Toplam başabaş = 250.000 / 50 = 5.000 adet.'),
  ('Kısa dönemde birim satış fiyatı 85 TL, birim değişken maliyeti 70 TL ve birim sabit maliyeti 25 TL olan zarar eden bir fabrika, geçici talep daralmasında üretimi durdurup durdurmama kararını nasıl vermelidir?', 'Fiyat değişken maliyeti aşıp sabit giderlere 15 TL katkı sağladığı için üretime devam etmelidir', ['Toplam birim maliyet 95 TL olduğu ve birim başına 10 TL zarar edildiği için derhal kapanmalıdır', 'Sabit maliyetleri sıfırlamak amacıyla üretimi yarıya indirip fiyatı iki katına çıkarmalıdır', 'Amortisman giderlerini tamamen durdurabilmek için makineleri geçici olarak mühürlemelidir'], 'Kısa dönemde sabit giderler dursa da ödenecektir; satış fiyatı birim değişken maliyeti (85 > 70) aştığı sürece her birim sabit gider yükünü 15 TL hafifletir.'),
  ('Bir üretim işletmesinde dönem içi direkt ilk madde ve malzeme gideri 200.000 TL, direkt işçilik 150.000 TL ve genel üretim giderleri 100.000 TL\'dir. Dönem başı yarı mamul 40.000 TL, dönem sonu yarı mamul 60.000 TL ise üretilen mamul maliyeti kaç TL\'dir?', '430.000 TL', ['450.000 TL', '470.000 TL', '390.000 TL'], 'Toplam üretim maliyeti = 200.000 + 150.000 + 100.000 = 450.000 TL; Üretilen mamul maliyeti = 450.000 + 40.000 - 60.000 = 430.000 TL.'),
  ('Bir işletme birim fiyatı 250 TL olan üründen ayda 4.000 adet satmakta ve 120.000 TL faaliyet kârı elde etmektedir. Katkı oranı %32 olduğuna göre bu işletmenin aylık sabit maliyeti kaç TL\'dir?', '200.000 TL', ['320.000 TL', '180.000 TL', '240.000 TL'], 'Toplam satış = 4.000 x 250 = 1.000.000 TL; Toplam katkı payı = 1.000.000 x 0,32 = 320.000 TL; Sabit maliyet = 320.000 - 120.000 = 200.000 TL.'),
  ('Toplam kullanım kapasitesi 500.000 kilometre, alım maliyeti 1.150.000 TL ve hurda değeri 150.000 TL olan bir tır, ilk yıl 85.000 kilometre yol yapmıştır. Üretim (kullanım) miktarı yöntemine göre ilk yılın amortisman gideri kaç TL\'dir?', '170.000 TL', ['195.500 TL', '230.000 TL', '150.000 TL'], 'Kilometre başına amortisman = (1.150.000 - 150.000) / 500.000 = 2 TL/km; İlk yıl gideri = 85.000 x 2 = 170.000 TL.'),
  ('Bir şirketin net satışları geçen döneme göre aynı kalmasına rağmen brüt kâr marjı %42\'den %36\'ya gerilemiş, buna karşılık esas faaliyet kârı marjı %15\'ten %17\'ye yükselmiştir. Bu tablo nasıl açıklanabilir?', 'Üretim/tedarik maliyetleri artarken pazarlama ve yönetim giderlerinde sıkı tasarruf sağlanmıştır', ['Satılan malın maliyeti düşerken banka kredi faizleri ve vergi oranları hızla yükselmiştir', 'Satış iadeleri tamamen sıfırlanırken araştırma-geliştirme harcamaları iki katına çıkmıştır', 'Amortisman süresi kısaltılırken dönem sonu stokları olduğundan çok daha yüksek değerlenmiştir'], 'Brüt kâr marjının 6 puan düşmesi SMM oranının arttığını, faaliyet kâr marjının 2 puan artması ise faaliyet giderlerinin satışlara oranla 8 puan azaltıldığını gösterir.'),
  ('Dönem başında tanesi 80 TL\'den 100 adet mal bulunan depoya, dönem içinde tanesi 110 TL\'den 300 adet mal alınmıştır. Dönem sonunda depoda 120 adet mal kaldığına göre, FIFO ile ağırlıklı ortalama yöntemleri arasındaki satılan malın maliyeti farkı kaç TL\'dir?', '900 TL', ['1.200 TL', '600 TL', '1.500 TL'], 'Satılan miktar = 400 - 120 = 280 adet. FIFO SMM = (100 x 80) + (180 x 110) = 8.000 + 19.800 = 27.800 TL. Ort. birim = (8.000 + 33.000)/400 = 102,5 TL; Ort. SMM = 280 x 102,5 = 28.700 TL. Fark = 900 TL.'),
  ('Mevcut durumda tam kapasitenin altında (%70 kapasiteyle) çalışan, birim satış fiyatı 100 TL, birim değişken maliyeti 55 TL ve birim sabit maliyeti 30 TL olan bir üreticiye, normal pazarını etkilemeyecek tek seferlik 1.000 adetlik yurt dışı özel sipariş için birim başına 68 TL teklif edilmiştir. İşletme ne yapmalıdır?', 'Birim başına 13 TL ek katkı payı sağlayacağı için özel siparişi kabul etmelidir', ['Toplam birim maliyet olan 85 TL\'nin altında kaldığı için teklifi reddetmelidir', 'Yalnızca birim fiyat 100 TL olan standart liste fiyatına çekilirse kabul etmelidir', 'Sabit maliyetleri 30 TL artırmamak için mevcut yurt içi satışlarını durdurmalıdır'], 'Atıl kapasite varken sabit maliyetler değişmez; 68 TL\'lik özel fiyat 55 TL\'lik birim değişken maliyeti aştığından (68 - 55 = 13 TL) faaliyet kârını 13.000 TL artırır.'),
  ('Bir işletmede güvenlik marjı oranı %25 ve katkı oranı %40 ise, bu işletmenin net satış hasılatı üzerinden esas faaliyet kârı marjı yüzde kaçtır?', '%10', ['%15', '%16', '%65'], 'Esas faaliyet kârı marjı = Güvenlik marjı oranı x Katkı oranı = 0,25 x 0,40 = 0,10 yani %10\'dur.'),
  ('Maliyeti 250.000 TL ve ekonomik ömrü 4 yıl olan bir makine için azalan bakiyeler yöntemi (%50 oran) uygulanmaktadır. Dördüncü (son) yıl ayrılacak amortisman gideri kaç TL olur?', '31.250 TL', ['15.625 TL', '62.500 TL', '125.000 TL'], '1. yıl: 125.000 (kalan 125.000); 2. yıl: 62.500 (kalan 62.500); 3. yıl: 31.250 (kalan 31.250); son yıl kalan net değerin tamamı olan 31.250 TL gider yazılır.'),
  ('Birim satış fiyatı 100 TL, birim değişken maliyeti 60 TL ve sabit maliyeti 120.000 TL olan bir işletme, reklam bütçesini 40.000 TL artırıp birim satış fiyatını %10 yükseltirse yeni başabaş üretim miktarı eski başabaş miktarına göre nasıl değişir?', 'Eski başabaş miktarına göre 200 adet artar', ['Eski başabaş miktarına göre 400 adet azalır', 'Tam olarak 3.000 adette sabit kalır', 'Eski başabaş miktarının yarısına düşer'], 'Eski başabaş = 120.000 / (100 - 60) = 3.000 adet. Yeni fiyat = 110 TL, yeni katkı = 50 TL, yeni sabit = 160.000 TL. Yeni başabaş = 160.000 / 50 = 3.200 adet (200 adet artar).'),
  ('Net satışları 1.200.000 TL, değişken maliyetleri 720.000 TL, sabit faaliyet giderleri 300.000 TL ve faiz giderleri 60.000 TL olan bir şirkette faaliyet kaldıracı derecesi kaçtır?', '2,67', ['4,00', '2,00', '1,50'], 'Toplam katkı payı = 1.200.000 - 720.000 = 480.000 TL; Faaliyet kârı = 480.000 - 300.000 = 180.000 TL; Faaliyet kaldıracı = 480.000 / 180.000 = 2,67.'),
  ('Enflasyonun yüksek olduğu bir ekonomide tarihi maliyetlerle ayrılan amortisman tutarlarının işletme sermayesi üzerindeki en önemli finansal riski nedir?', 'Ayrılan amortisman fonunun makine yenileme maliyetinin çok altında kalması ve zahiri kâr üzerinden vergi ödenmesi', ['Amortisman giderlerinin güncel satış fiyatlarından büyük çıkarak şirketi sürekli kağıt üzerinde zararda göstermesi', 'Duran varlıkların bilançodaki net defter değerinin piyasa değerinin çok üzerine çıkarak aktifleri şişirmesi', 'Stok devir hızını yapay biçimde düşürerek işletmenin kısa vadeli banka kredilerine erişimini engellemesi'], 'Tarihi alış bedeli üzerinden ayrılan düşük amortisman, kârı yapay biçimde (zahiri kâr) yüksek gösterir; vergi yoluyla sermaye erimesine ve yenileme fonu yetersizliğine yol açar.'),
  ('Borçlanma faiz oranının, şirketin varlıklarından elde ettiği vergi ve faiz öncesi kârlılık oranından daha düşük olduğu bir durumda borç kullanımının artırılması özkaynak kârlılığını (ROE) nasıl etkiler?', 'Olumlu kaldıraç etkisi yaratarak özkaynak kârlılığını yükseltir', ['Finansman giderlerini artırdığı için özkaynak kârlılığını kesinlikle düşürür', 'Sadece cari oranı değiştirir, özkaynak kârlılığı üzerinde hiçbir etki yaratmaz', 'Aktif devir hızını sıfırlayarak şirketin net kâr marjını negatife çevirir'], 'Varlık getirisi borç maliyetinden yüksek olduğunda yabancı kaynak kullanımı pozitif kaldıraç etkisi yaratır ve ROE\'yi artırır.'),
  ('İki şirketin net kâr marjları ve aktif devir hızları birebir aynı olmasına rağmen A şirketinin özkaynak kârlılığı (ROE) B şirketinden daha yüksekse bunun nedeni nedir?', 'A şirketinin finansal kaldıraç oranının (borç kullanım düzeyinin) daha yüksek olması', ['A şirketinin stok devir hızının sıfır olması ve hiç ticari alacağının bulunmaması', 'B şirketinin satış gelirlerinin tamamını peşin olarak tahsil ediyor olması', 'B şirketinin amortisman giderlerinin A şirketine kıyasla daha yüksek olması'], 'DuPont eşitliğine göre net kâr marjı ve aktif devir hızı eşitken ROE\'yi yükselten tek faktör daha yüksek özkaynak çarpanı, yani daha yüksek finansal kaldıraçtır.'),
  ('Hızla büyüyen ve satışlarını ikiye katlayan kârlı bir KOBİ\'nin nakit krizi yaşayarak iflas tehlikesiyle karşılaşmasını açıklayan "aşırı ticaret (overtrading)" olgusunun temel mekanizması hangisidir?', 'Artan satış hacmini desteklemek için gereken stok ve alacak finansmanının mevcut nakit üretimini aşması', ['Satışlar arttıkça birim sabit maliyetlerin yükselerek brüt kâr marjını otomatikman sıfırlaması', 'Şirketin büyüdükçe vergi diliminin düşmesi ve devlete daha az kurumlar vergisi ödemesi', 'Üretim kapasitesi büyüdükçe tedarikçilerin peşin ödeme kabul etmeyip vadeyi zorla uzatması'], 'Hızlı büyüme sırasında stok alımı ve vadeli satışlar (alacaklar) için peşin kaynak gerekir; işletme sermayesi yetersizse kârlı büyüme ciddi nakit açığı yaratır.'),
  ('Cari oranı 0,8 olan bir işletme, 6 ay vadeli satıcı kredisiyle (veresiye) 200.000 TL değerinde ticari mal satın alırsa cari oranı nasıl değişir?', 'Cari oran 0,8\'in üzerine çıkarak 1\'e yaklaşır', ['Cari oran 0,8\'in altına inerek daha da küçülür', 'Pay ve payda eşit arttığı için cari oran 0,8 olarak kalır', 'Kısa vadeli borç arttığı için cari oran sıfırlanır'], 'Cari oran 1\'den küçükken (örneğin 400.000 / 500.000 = 0,8), pay ve paydaya aynı pozitif sayı (200.000) eklendiğinde oran büyür (600.000 / 700.000 = 0,857) ve 1\'e yaklaşır.'),
  ('Stok devir süresi 50 gün, alacak tahsil süresi 40 gün ve borç ödeme süresi 30 gün olan bir işletmenin nakit dönüşüm süresi kaç gündür ve bu ne anlama gelir?', '60 gündür; işletme tedarikçiye ödeme yaptıktan ortalama 60 gün sonra satıştan nakit tahsil eder', ['120 gündür; işletmenin yılda yalnızca üç kez üretim yapabildiğini gösterir', '20 gündür; işletmenin müşterilerden peşin tahsilat yapıp vadeli ödediğini kanıtlar', '90 gündür; işletmenin kısa vadeli banka kredisi kullanmadan çalışabildiğini gösterir'], 'Nakit dönüşüm süresi = Stok Devir Süresi + Alacak Tahsil Süresi - Borç Ödeme Süresi = 50 + 40 - 30 = 60 gündür; bu 60 günlük nakit açığının çalışma sermayesiyle finanse edilmesi gerekir.'),
  ('Net kâr marjı %10, aktif devir hızı 1,5 ve finansal kaldıraç oranı (Toplam Borç / Toplam Aktif) %50 olan bir işletmenin özkaynak kârlılığı (ROE) yüzde kaçtır?', '%30', ['%15', '%22,5', '%7,5'], 'Kaldıraç %50 ise Özkaynak / Toplam Aktif = %50, dolayısıyla Özkaynak Çarpanı (Aktif / Özkaynak) = 2\'dir. ROE = %10 x 1,5 x 2 = %30 olur.'),
  ('Mevsimsel satış yapan bir tekstil firmasının kış sezonu öncesinde yoğun hammadde alımı ve üretim yaptığı sonbahar aylarında finansal oranlarında hangi değişimin görülmesi normal karşılanır?', 'Stoklar ve kısa vadeli ticari borçlar şiştiği için asit-test oranının geçici olarak düşmesi', ['Henüz satış yapılmadığı halde tahsilatların artmasıyla nakit oranının zirveye çıkması', 'Özkaynak kârlılığının üretim aşamasında yıllık en yüksek seviyesine ulaşması', 'Duran varlıkların tamamı elden çıkarıldığı için aktif devir hızının sonsuza gitmesi'], 'Sezon öncesi stok biriktirilirken nakit harcanır veya kısa vadeli borçlanılır; bu dönemde stoklar arttığı ve hazır değerler azaldığı için asit-test oranının düşmesi doğaldır.'),
  ('Bir şirketin FAVÖK (EBITDA) marjı oldukça yüksek olmasına rağmen serbest nakit akışı (Free Cash Flow) sürekli negatif çıkıyorsa bunun en güçlü açıklaması hangisidir?', 'Şirketin çok ağır maddi duran varlık yatırımları (CAPEX) yapması ve işletme sermayesi ihtiyacının hızla artması', ['Amortisman ve itfa paylarının gelir tablosunda kârdan düşülmesinin nakit çıkışına yol açması', 'Şirketin hiç banka kredisi kullanmaması ve finansman giderinin sıfıra eşit olması', 'Müşterilerden peşin tahsilat yapılırken tedarikçilere 180 gün vadeli ödeme yapılması'], 'Serbest nakit akışı hesaplanırken işletme nakit akışından sermaye harcamaları (CAPEX) ve işletme sermayesi artışları düşülür; yüksek yatırım ve işletme sermayesi artışı serbest nakit akışını negatife çevirebilir.'),
  ('Yüksek enflasyon ortamında stoklarını İlk Giren İlk Çıkar (FIFO) yöntemiyle değerleyen bir işletmede görülen "fiktif (zahiri) kâr" olgusu nakit akışını nasıl etkiler?', 'Düşük maliyetli eski stokların satışı kağıt üzerinde kârı şişirir; artan vergi ve temettü çıkışları yerine koyma maliyeti yükselen stoklar karşısında nakit erimesine yol açar', ['Satılan malın maliyeti olduğundan yüksek göründüğü için şirket zarar açıklar ve hiç vergi ödemeyerek kasasında büyük bir nakit fazlası biriktirir', 'Enflasyon stok devir hızını durdurduğu için cari oran sıfırlanır ancak işletme faaliyetlerinden nakit akışı rekor düzeyde fazla verir', 'Yabancı kaynak kullanımı kendiliğinden yasaklandığı için şirketin finansal kaldıraç oranı bir hesap dönemi içinde tamamen sıfırlanır'], 'FIFO yönteminde enflasyonist ortamda eski ucuz maliyetler gider yazılır, kağıt üzerinde yüksek kâr çıkar; bu kâr üzerinden ödenen vergi ve temettü, zamlanan yeni stoğu yerine koymak için gereken nakdi eritir.'),
  ('Bir şirketin özkaynak kârlılığı (ROE) %18\'den %28\'e yükselirken aktif kârlılığı (ROA) %12\'den %9\'a gerilemiştir. Bu iki zıt eğilim bir arada değerlendirildiğinde aşağıdaki sonuçlardan hangisine ulaşılır?', 'Şirketin operasyonel varlık verimliliği düşerken borçlanma (kaldıraç) oranı ciddi biçimde artırılmıştır', ['Şirket tüm banka borçlarını kapatarak tamamen özsermaye ile çalışma modeline geçmiştir', 'Net kâr marjı ve aktif devir hızı aynı anda yükselerek borç maliyetini sıfırlamıştır', 'Şirket yeni hisse senedi ihraç ederek özkaynaklarını toplam aktiflerinden daha hızlı büyütmüştür'], 'ROA düşerken ROE\'nin yükselmesi ancak Özkaynak Çarpanının (Toplam Aktif / Özkaynak) sert biçimde artmasıyla, yani borç oranının yükselmesiyle mümkündür.'),
  ('Net satışları 4.000.000 TL, brüt kâr marjı %30, faaliyet giderleri 600.000 TL ve faiz giderleri 150.000 TL olan bir şirketin faiz karşılama oranı kaçtır (başka gelir/gider yoktur)?', '4,0', ['8,0', '3,0', '5,0'], 'Brüt kâr = 4.000.000 x %30 = 1.200.000 TL. Faaliyet kârı (FVÖK) = 1.200.000 - 600.000 = 600.000 TL. Faiz karşılama oranı = 600.000 / 150.000 = 4,0\'tır.'),
  ('Bankadan kredi talep eden bir işletmenin bilançosunda cari oran 2,1 ve asit-test oranı 1,6 görünmesine rağmen banka kredi komitesinin "likidite kalitesi zayıf" gerekçesiyle talebi reddetmesinin en haklı nedeni hangisi olabilir?', 'Ticari alacakların büyük kısmının vadesi çoktan geçmiş ve tahsili gecikmiş grup içi alacaklardan oluşması', ['Şirketin stok devir hızının sektör ortalamasından daha yüksek ve verimli seyretmesi', 'Kısa vadeli yabancı kaynakların tamamının faizsiz tedarikçi borçlarından meydana gelmesi', 'İşletme faaliyetlerinden elde edilen nakit akışının net dönem kârından daha yüksek olması'], 'Asit-test oranı ticari alacakları likit kabul eder; ancak bu alacaklar tahsil kabiliyeti düşük veya vadesi geçmiş şüpheli alacaklarsa kağıt üzerindeki 1,6 oranı gerçek borç ödeme gücünü yansıtmaz.'),
  ('İşletme sermayesi yönetiminde "atak (agresif) finansman stratejisi" uygulayarak süreklilik gösteren dönen varlıklarının bile bir kısmını kısa vadeli kredilerle finanse eden bir şirketin karşılaştığı temel ödünleşim (trade-off) nedir?', 'Kısa vadeli borçlanma genellikle daha ucuz olduğu için kârlılık potansiyeli artarken yenileme ve likidite riski yükselir', ['Likidite riski tamamen ortadan kalkarken şirketin uzun vadeli faiz giderleri aşırı derecede artar', 'Cari oran 3,0 seviyesinin üzerine çıkarken şirketin aktif devir hızı yarı yarıya düşer', 'Stokların bozulma riski azalırken ortakların özkaynak üzerindeki oy hakları sınırlandırılır'], 'Agresif strateji daha düşük faizli kısa vadeli kaynaklara dayandığı için beklenen ROE\'yi artırabilir; ancak faiz artışı veya kredi daralmasında borcu çevirememe (likidite) riskini büyütür.'),
  ('Dönem içinde net kârı 180.000 TL, amortisman gideri 40.000 TL olan bir şirkette stoklar 50.000 TL artmış, ticari alacaklar 30.000 TL azalmış ve ticari borçlar 25.000 TL artmıştır. İşletme faaliyetlerinden nakit akışı kaç TL\'dir?', '225.000 TL', ['165.000 TL', '265.000 TL', '175.000 TL'], 'Nakit akışı = 180.000 (Net kâr) + 40.000 (Amortisman) - 50.000 (Stok artışı) + 30.000 (Alacak azalışı) + 25.000 (Ticari borç artışı) = 225.000 TL\'dir.'),
  ('Aynı sektörde faaliyet gösteren X ve Y şirketlerinden X\'in brüt kâr marjı %45, net kâr marjı %5; Y\'nin ise brüt kâr marjı %22, net kâr marjı %11\'dir. Bu veriler ışığında X şirketi hakkında hangi değerlendirme en tutarlıdır?', 'Ürünü yüksek katma değerle üretip fiyatlayabilmekte ancak aşırı faaliyet veya finansman giderleri kârı eritmektedir', ['Hammadde tedarikinde Y şirketine göre çok daha pahalıya alım yapmakta ve üretimde zarar etmektedir', 'Hiçbir yabancı kaynak kullanmadığı için vergi kalkanından yararlanamamakta ve brüt marjı şişmektedir', 'Stok devir hızı yüksek olduğu için işletme faaliyetlerinden nakit akışı kesinlikle Y şirketinden fazladır'], '%45 brüt marj üretim/fiyatlama gücünün çok iyi olduğunu gösterir; ancak net marjın %5\'e inmesi genel yönetim, pazarlama veya ağır faiz yükünün kârı yuttuğunu kanıtlar.'),
  ('Kâr eden bir e-ticaret girişiminin müşterilerden kredi kartıyla peşin tahsilat yapmasına rağmen ciddi nakit sıkışıklığı yaşaması aşağıdaki senaryolardan hangisiyle en iyi açıklanır?', 'Yüksek müşteri iade oranları, peşin ödenen agresif dijital reklam bütçeleri ve depo/yazılım yatırımlarının nakdi hızla tüketmesi', ['Müşterilerin peşin ödeme yapmasının bilançodaki ticari alacakları şişirerek tahsilat süresini uzatması', 'Gelir tablosunda ayrılan amortisman giderlerinin her ay sonunda nakit olarak vergi dairesine yatırılması', 'Tedarikçilere yapılan ödemelerin 90 gün vadeli olmasının kasadaki nakit girişini tamamen durdurması'], 'Peşin satış yapılsa dahi yoğun duran varlık/yazılım yatırımları (CAPEX), peşin ödenen stoklar veya kârı aşan peşin pazarlama/iade çıkışları nakit darboğazı yaratabilir.'),
  ('Bir işletme 90.000 TL net defter değerli bir aracı 110.000 TL peşin bedelle sattığında nakit akış tablosunda nasıl bir etki oluşur?', 'Yatırım faaliyetlerinde 110.000 TL nakit girişi görünür', ['Yatırım faaliyetlerinde yalnız 20.000 TL kâr girişi yazılır', 'Finansman faaliyetlerinde 110.000 TL nakit girişi oluşur', 'İşletme faaliyetlerinde 90.000 TL nakit girişi kaydedilir'], 'Duran varlık satışından elde edilen toplam nakit (110.000 TL) yatırım faaliyetlerinde giriş yazılır; 20.000 TL satış kârı dolaylı yöntemde işletme kârından düşülür.'),
  ('Net kârı 200.000 TL olan bir şirketin dönem amortismanı 40.000 TL, stok artışı 30.000 TL ve ticari borç artışı 15.000 TL ise işletme faaliyetlerinden nakit akışı kaç TL\'dir?', '225.000 TL', ['175.000 TL nakit akışı', '255.000 TL nakit akışı', '195.000 TL nakit akışı'], 'İşletme nakit akışı = 200.000 + 40.000 (amortisman) − 30.000 (stok artışı) + 15.000 (borç artışı) = 225.000 TL olur.'),
  ('İşletme faaliyetlerinden güçlü nakit üreten, yatırım nakit akışı negatif ve finansman nakit akışı negatif olan bir şirket genellikle hangi yaşam evresindedir?', 'Olgun ve kendi nakdiyle büyüyen', ['Yeni kurulmuş ve dış fon arayan', 'İflas eşiğinde varlık tasfiye eden', 'Sadece kredi çekerek faaliyet sürdüren'], 'İşletme nakit fazlasıyla hem yatırım yapabilen hem de borç ödeyip temettü dağıtabilen şirket olgun ve finansal açıdan sağlıklı yapıdadır.'),
  ('Dönem içinde stokların 50.000 TL azalması dolaylı yöntemle hazırlanan nakit akış tablosunda net kâra nasıl yansıtılır?', '50.000 TL eklenir', ['50.000 TL net kârdan çıkarılır', 'Yatırım faaliyetlerine 50.000 TL eklenir', 'Finansman faaliyetlerinden 50.000 TL düşülür'], 'Stokların azalması, daha önce nakit bağlanmış malların satılarak nakde dönüştüğünü veya yeni alım yapılmadığını gösterdiğinden net kâra eklenir.'),
  ('Bir şirketin stok devir hızı 36 günde bir, alacak tahsil süresi 44 gün ve ticari borç ödeme süresi 50 gün ise nakit dönüşüm süresi (nakit çevrim döngüsü) kaç gündür?', '30 gün', ['130 gün nakit döngüsü', '42 gün nakit döngüsü', '80 gün nakit döngüsü'], 'Nakit dönüşüm süresi = Stokta Kalma Süresi + Alacak Tahsil Süresi − Borç Ödeme Süresi = 36 + 44 − 50 = 30 gündür.'),
  ('Bir perakende zincirinin nakit dönüşüm süresinin negatif çıkması işletmenin nakit yönetimi açısından ne anlama gelir?', 'Tedarikçilere ödeme yapmadan önce nakdi tahsil ettiği', ['Müşterilerden hiç tahsilat yapamadığı ve zarar ettiği', 'Stokların depoda bir yıldan uzun süre beklediği', 'Bankalardan sürekli yüksek faizli kredi çektiği'], 'Negatif nakit dönüşüm süresi, işletmenin malları peşin satıp tedarikçilerine daha ileri vadede ödeme yaparak tedarikçi finansmanıyla çalıştığını gösterir.'),
  ('Net kâr marjı %5, aktif devir hızı 2 ve özsermaye çarpanı (Toplam Varlık/Özkaynak) 1,5 olan bir şirketin DuPont analizine göre özkaynak kârlılığı (ROE) yüzde kaçtır?', '%15', ['%10 özkaynak kârlılığı', '%8,5 özkaynak kârlılığı', '%20 özkaynak kârlılığı'], 'DuPont eşitliğine göre ROE = Net Kâr Marjı × Aktif Devir Hızı × Özsermaye Çarpanı = 0,05 × 2 × 1,5 = 0,15 yani %15 olur.'),
  ('Cari oranı 0,80 olan bir şirket kısa vadeli bir borcunu elindeki nakitle öderse cari oran nasıl değişir?', 'Cari oran düşer', ['Cari oran yükselerek 1\'e yaklaşır', 'Cari oran hiçbir şekilde değişmez', 'Cari oran özkaynak oranına eşitlenir'], 'Başlangıçta 1\'den küçük bir oranın pay ve paydasından eşit pozitif tutar çıkarıldığında oran daha da küçülür.'),
  ('Aylık satışları 500.000 TL ve başabaş satış tutarı 350.000 TL olan bir şirketin güvenlik marjı oranı yüzde kaçtır?', '%30', ['%70 güvenlik marjı', '%42,8 güvenlik marjı', '%25 güvenlik marjı'], 'Güvenlik marjı = 500.000 − 350.000 = 150.000 TL\'dir. Güvenlik marjı oranı = 150.000 / 500.000 = %30 bulunur.'),
  ('Faaliyet kaldıracı derecesi 4 olan bir işletmenin satış hacmi %10 arttığında faaliyet kârının (FVÖK) yüzde kaç artması beklenir?', '%40', ['%14 faaliyet kârı artışı', '%25 faaliyet kârı artışı', '%2,5 faaliyet kârı artışı'], 'Faaliyet kârındaki yüzdelik değişim = Faaliyet Kaldıracı × Satış Hacmi Yüzdelik Değişimi = 4 × %10 = %40 olur.'),
  ('Yüksek faaliyet kaldıracına sahip bir işletmenin ekonomik durgunluk dönemlerinde satışlarının düşmesi neden daha risklidir?', 'Sabit giderler düşmediği için kâr çok hızlı erir', ['Değişken maliyetler satışlardan daha hızlı artar', 'Başabaş noktası kendiliğinden yarıya iner', 'Özkaynaklar otomatik olarak nakde dönüşür'], 'Yüksek sabit maliyetler satış düşse bile sürdüğünden, faaliyet kaldıracı satış azalışının kâr üzerindeki olumsuz etkisini de aynı ölçüde büyütür.'),
  ('Diğer tüm koşullar sabitken birim değişken maliyetin düşmesi başabaş noktasını nasıl etkiler?', 'Başabaş noktası düşer', ['Başabaş noktası yukarı doğru yükselir', 'Başabaş noktası hiçbir değişiklik göstermez', 'Başabaş noktası toplam sabit maliyete eşitlenir'], 'Birim değişken maliyetin azalması birim katkı payını artırır; sabit maliyet daha az ürünle karşılanacağı için başabaş noktası düşer.'),
  ('Atıl kapasitesi bulunan bir fabrikanın normal satış fiyatının altında fakat birim değişken maliyetinin üzerinde gelen tek seferlik özel bir siparişi değerlendirirken temel kârlılık ölçütü nedir?', 'Siparişin pozitif katkı payı yaratması', ['Sipariş fiyatının toplam ortalama maliyeti aşması', 'Sabit kira giderinin siparişe göre azalması', 'Sipariş tutarının başabaş cirosunu geçmesi'], 'Sabit maliyetler zaten katlanıldığı için, normal pazarı bozmayan ve atıl kapasiteyle üretilen özel sipariş birim değişken maliyeti aşarsa pozitif katkı payı yaratarak kârı artırır.'),
  ('Aralık ayında gelecek yılın ocak ayında teslim edilecek ürünler için müşteriden peşin alınan 50.000 TL avans, tahakkuk esasına göre yıl sonu bilançosunda nasıl raporlanır?', 'Kısa vadeli borç', ['Cari dönem satış geliri hasılatı', 'Dönen varlık ticari alacağı', 'Maddi duran varlık artışı'], 'Henüz mal teslim edilip gelir kazanılmadığı için alınan nakit işletmenin müşteriye mal teslim yükümlülüğünü temsil eden bir borç (ertelenmiş gelir) olarak kaydedilir.'),
  ('Aynı duran varlık için doğrusal yöntem yerine azalan bakiyeler yöntemi seçildiğinde, varlığın ilk kullanım yılında finansal tablolarda hangi etki gözlenir?', 'Daha yüksek gider ve daha düşük vergi', ['Daha yüksek net kâr ve yüksek vergi', 'Daha yüksek net defter değeri', 'Daha yüksek işletme nakit çıkışı'], 'Azalan bakiyeler yöntemi ilk yılda daha büyük amortisman gideri yaratarak dönem kârını ve ödenecek kurumlar vergisini azaltır (vergi kalkanı).'),
  ('Maliyeti 300.000 TL, kalıntı değeri 20.000 TL ve tahmini toplam çalışma ömrü 70.000 saat olan bir makine ilk yıl 15.000 saat çalıştırılırsa üretim (faaliyet) miktarı yöntemine göre ilk yıl amortismanı kaç TL olur?', '60.000 TL', ['64.285 TL ilk yıl amortismanı', '45.000 TL ilk yıl amortismanı', '75.000 TL ilk yıl amortismanı'], 'Saat başına amortisman = (300.000 − 20.000) / 70.000 = 4 TL/saat; ilk yıl amortismanı = 15.000 × 4 = 60.000 TL olarak hesaplanır.'),
  ('Borç kullanan kârlı bir işletmede borçlanma faiz oranı aktif getirisinden (ROA) düşük olduğunda özkaynak kârlılığı (ROE) nasıl etkilenir?', 'ROE, ROA\'nın üzerine çıkar', ['ROE, ROA\'nın altına düşer', 'ROE ile ROA birbirine eşitlenir', 'ROE her koşulda negatife döner'], 'Pozitif finansal kaldıraç etkisi sayesinde varlık getirisi borç maliyetini aştığında aradaki fark ortaklara kalır ve ROE, ROA\'dan yüksek gerçekleşir.'),
  ('Bir şirket 100.000 TL tutarındaki büyük bir üretim makinesi alımını yanlışlıkla aktifleştirmek yerine tamamını doğrudan ilk yıl gideri yazarsa, ilk yıl finansal tabloları nasıl bozulur?', 'İlk yıl kârı ve varlıkları olması gerekenden düşük çıkar', ['İlk yıl kârı yüksek, varlıkları düşük görünür', 'İlk yıl kârı değişmez, borçları yapay biçimde büyür', 'Sonraki yıllarda amortisman gideri aşırı yükselir'], 'Varlık aktifleştirilmediği için ilk yıl gideri aşırı artar, net kâr ve toplam varlıklar olduğundan düşük raporlanır; sonraki yıllarda ise amortisman yazılamayacağından kâr yapay olarak yüksek görünür.'),
  ('Fiyatların sürekli arttığı bir ekonomide FIFO yerine LIFO (Son Giren İlk Çıkar) yönteminin kullanılması işletmenin vergi yükü ve nakit akışını nasıl etkiler?', 'Satılan mal maliyeti artar, vergi çıkışı azalır', ['Brüt kâr yükselir, vergi ödemesi artar', 'Dönem sonu stok değeri en yüksek düzeye çıkar', 'Amortisman gideri doğrudan sıfıra düşer'], 'Enflasyon ortamında LIFO en yüksek güncel maliyetleri gidere yazarak kârı düşürür; böylece daha az gelir/kurumlar vergisi ödenir ve nakit çıkışında tasarruf sağlanır (TFRS\'de LIFO yasaktır, ABD GAAP\'te izinlidir).'),
  ('Üretim miktarının satış miktarından fazla olduğu (stokların arttığı) bir dönemde tam maliyet yöntemi, değişken maliyet yöntemine kıyasla faaliyet kârını nasıl gösterir?', 'Daha yüksek gösterir', ['Daha düşük olarak raporlar', 'Her koşulda birebir eşit gösterir', 'Doğrudan negatife çevirir'], 'Tam maliyet yönteminde satılmayan stokların içinde sabit genel üretim giderlerinin bir kısmı bilançoya aktarıldığından dönemin gideri azalır ve kâr daha yüksek görünür.'),
  ('Bir atölye 200 birim üretirken toplam maliyeti 54.000 TL, 250 birim üretirken toplam maliyeti 64.000 TL oluyorsa en yüksek–en düşük noktalar yöntemine göre birim değişken maliyet ve toplam sabit maliyet nedir?', '200 TL değişken, 14.000 TL sabit', ['250 TL değişken, 14.000 TL sabit', '200 TL değişken, 40.000 TL sabit', '180 TL değişken, 18.000 TL sabit'], 'Birim değişken maliyet = (64.000 − 54.000) / (250 − 200) = 10.000 / 50 = 200 TL; sabit maliyet = 54.000 − (200 × 200) = 14.000 TL\'dir.'),
  ('Ağırlıklı ortalama birim katkı payı 38 TL ve toplam sabit maliyeti 190.000 TL olan çok ürünlü bir işletmenin toplam başabaş satış miktarı kaç adettir?', '5.000 adet', ['3.800 adet toplam satış', '6.333 adet toplam satış', '4.750 adet toplam satış'], 'Toplam başabaş satış adedi = 190.000 / 38 = 5.000 adet olur; satış karışımı oranlarına göre ürünlere dağıtılır.'),
  ('X ürününün birim katkı payı 60 TL olup üretimi 3 makine saati, Y ürününün birim katkı payı 50 TL olup üretimi 2 makine saati sürmektedir. Makine saati kısıtlıysa hangi ürün önceliklidir ve saatlik katkı payı farkı kaç TL\'dir?', 'Y ürünü, saatte 5 TL fazla', ['X ürünü, saatte 10 TL fazla', 'X ürünü, saatte 5 TL fazla', 'Y ürünü, saatte 15 TL fazla'], 'Saat başı katkı payı X için 60/3 = 20 TL, Y için 50/2 = 25 TL\'dir; Y ürünü kısıtlı saat başına 5 TL daha fazla katkı sağlar.'),
  ('FAVÖK (EBITDA) göstergesinin tek başına işletmenin serbest nakit akışı yerine kullanılmasının temel sakıncası nedir?', 'Sermaye harcamalarını ve işletme sermayesi değişimini dışlaması', ['Amortisman giderini iki kez kârdan düşmesi', 'Faaliyet giderlerinin tamamını görmezden gelmesi', 'Yalnızca banka kredilerinin ana parasını ölçmesi'], 'FAVÖK nakit dışı amortismanı geri ekler ancak zorunlu makine yenileme yatırımlarını (CAPEX), alacak-stok artışlarını, faiz ve vergi ödemelerini hesaba katmaz.'),
  ('Bir işletmenin yıl sonunda yapması gereken 15.000 TL tutarındaki faiz gideri tahakkuk kaydını unutması bilançoyu ve gelir tablosunu nasıl etkiler?', 'Net kâr yüksek, borçlar düşük görünür', ['Net kâr düşük, varlıklar yüksek görünür', 'Net kâr değişmez, borçlar yüksek görünür', 'Özkaynaklar düşük, borçlar yüksek görünür'], 'Gider kaydı atlandığı için dönem net kârı ve özkaynaklar 15.000 TL yüksek, ödenecek gider tahakkukları (borçlar) ise 15.000 TL düşük çıkar.'),
  ('Bir işletmenin ticari borç ödeme süresinin önceki yıla göre 35 günden 85 güne çıkması, aynı dönemde nakit oranı da hızla düşüyorsa öncelikle neyi düşündürür?', 'Likidite sıkışıklığı nedeniyle ödemelerin aksadığını', ['Tedarikçilerden yüksek peşin alım iskontosu alındığını', 'Satışların kârlılığının olağanüstü yükseldiğini', 'İşletmenin tüm kredilerini erken kapattığını'], 'Hem nakit oranının gerilemesi hem de tedarikçi ödeme süresinin sert biçimde uzaması şirketin faturalarını zamanında ödemekte zorlandığına işaret eder.'),
  ('Finansal analizde "finansman kuralı" (altın bilanço kuralı) olarak bilinen sağlıklı vade uyumu ilkesi neyi öngörür?', 'Duran varlıkların uzun vadeli kaynak ve özkaynakla finanse edilmesi', ['Duran varlıkların tamamının kısa vadeli ticari borçla alınması', 'Stokların yalnızca uzun vadeli tahvil ihracıyla karşılanması', 'Kasa nakdinin özkaynak toplamını mutlaka aşması'], 'Uzun ömürlü duran varlıkların kısa vadeli borçlarla finanse edilmesi vade uyumsuzluğu ve ödeme krizi yaratır; duran varlıklar özkaynak ve uzun vadeli borçla karşılanmalıdır.'),
  ('Bir şirketin dönem başı ticari alacakları 80.000 TL, dönem sonu ticari alacakları 110.000 TL ve yıllık kredili satışları 500.000 TL ise doğrudan yöntemde müşterilerden yapılan nakit tahsilat kaç TL\'dir?', '470.000 TL', ['530.000 TL nakit tahsilat', '500.000 TL nakit tahsilat', '390.000 TL nakit tahsilat'], 'Alacaklar 30.000 TL arttığı için satışların 30.000 TL\'lik kısmı henüz tahsil edilmemiştir: Nakit tahsilat = 500.000 − (110.000 − 80.000) = 470.000 TL olur.'),
  ('Bir işletme birim satış fiyatına %10 zam yaptığında birim değişken maliyeti ve sabit maliyetleri değişmezse katkı payı oranı ve başabaş noktası nasıl etkilenir?', 'Katkı payı oranı artar, başabaş noktası düşer', ['Katkı payı oranı düşer, başabaş noktası artar', 'Katkı payı oranı değişmez, başabaş noktası düşer', 'Katkı payı oranı artar, başabaş noktası yükselir'], 'Satış fiyatı arttığında birim katkı payı büyür ve katkı payı oranı yükselir; sabit maliyeti karşılamak için daha az ürün satmak yeterli olacağından başabaş noktası düşer.'),
  ('Maliyeti 180.000 TL, faydalı ömrü 4 yıl ve kalıntı değeri 0 TL olan bir ekipmana "yıllar toplamı rakamları" (azalan hızlandırılmış) yöntemiyle amortisman ayrılırsa ilk yıl amortisman gideri kaç TL olur?', '72.000 TL', ['45.000 TL ilk yıl amortismanı', '90.000 TL ilk yıl amortismanı', '54.000 TL ilk yıl amortismanı'], 'Yıllar toplamı = 1 + 2 + 3 + 4 = 10\'dur. İlk yıl oranı 4/10 olduğundan ilk yıl amortismanı = 180.000 × (4/10) = 72.000 TL hesaplanır.'),
  ('Bağımsız denetim raporunda bir şirketin finansal tablolarının geçerli muhasebe standartlarına her yönüyle uygun ve gerçeğe uygun sunulduğunu belirten görüş türü hangisidir?', 'Olumlu görüş', ['Şartlı (sınırlı olumlu) görüş', 'Görüş bildirmekten kaçınma', 'Olumsuz denetim görüşü'], 'Bağımsız denetçinin önemli bir yanlışlık veya kapsam sınırlaması tespit etmeden tabloların gerçeği dürüstçe yansıttığını teyit ettiği rapor olumlu görüştür.'),
  ('Dönem içinde bir müşteriden henüz teslim edilmemiş ürünler için alınan peşin avans, bilançoda hangi grupta raporlanır?', 'Kısa vadeli borçlar', ['Dönen varlıklar içerisindeki alacaklar', 'Özkaynaklar içerisindeki yedek akçeler', 'Gelir tablosundaki brüt satış hasılatı'], 'Mal veya hizmet henüz sunulmadığından işletmenin teslimat yükümlülüğü doğar; bu nedenle alınan avans kısa vadeli yabancı kaynak (borç) sayılır.'),
  ('Dönem sonunda gelir ve gider hesaplarının kapatılarak sonucun özkaynaklara devredilmesinde kullanılan geçici köprü hesap hangisidir?', 'Dönem Kârı veya Zararı', ['Geçmiş Yıllar Kârları hesabı', 'Genel Yönetim Giderleri hesabı', 'Ödenmiş Sermaye Yedekleri hesabı'], 'Tüm sonuç (gelir ve gider) hesapları dönem sonunda Dönem Kârı veya Zararı hesabına devredilerek kapatılır ve net sonuç bilançoya taşınır.'),
  ('Muhasebede tahakkuk esasına göre bir satış geliri hangi anda gelir tablosuna kaydedilir?', 'Mal teslim edilip hak doğduğunda', ['Müşteriden nakit tahsilat yapıldığında', 'Müşteri ürünü sözlü olarak sorduğunda', 'Gelecek mali yılın ilk günü geldiğinde'], 'Tahakkuk esası, nakit girişine bakılmaksızın gelirin kazanıldığı (teslimat veya hizmet ifasının gerçekleştiği) dönemde kaydedilmesini gerektirir.'),
  ('Eşleştirme (dönemsellik) ilkesine göre bir ürünün üretim veya tedarik maliyeti ne zaman gider olarak gelir tablosuna yansıtılır?', 'İlgili ürün satılarak gelir doğduğunda', ['Ürünün hammaddesi depoya ilk girdiğinde', 'Tedarikçiye nakit ödeme gerçekleştirildiğinde', 'Şirket yönetim kurulu kâr dağıttığında'], 'Eşleştirme ilkesi gereği, bir ürünün maliyeti satılana kadar stoklarda (aktifte) bekletilir ve satıldığı dönemde SMM olarak giderleştirilir.'),
  ('Fiyatların sürekli arttığı bir ortamda FIFO yönteminin kullanılması bilançodaki dönem sonu stok kalemini nasıl etkiler?', 'Güncel piyasa fiyatlarına yakın gösterir', ['En eski düşük alış fiyatlarıyla yansıtır', 'Stok değerini sıfıra doğru yaklaştırır', 'Dönen varlıklar toplamını yapay olarak düşürür'], 'FIFO\'da eski maliyetler satıldığı için depoda kalan stoklar en son alınan yüksek fiyatlı mallardan oluşur ve güncel değere yakın görünür.'),
  ('Fiyatların sürekli düştüğü (deflasyonist) bir ekonomide LIFO yöntemi ile FIFO yöntemi karşılaştırıldığında hangisi doğrudur?', 'LIFO daha yüksek net kâr üretir', ['FIFO daha yüksek brüt kâr üretir', 'LIFO daha yüksek SMM raporlar', 'FIFO daha düşük vergi matrahı doğurur'], 'Deflasyonda en son alınan mallar en ucuzdur; LIFO bu düşük maliyeti gider yazacağı için SMM düşer ve net kâr FIFO\'ya göre yüksek çıkar.'),
  ('Uluslararası Finansal Raporlama Standartları (UFRS/TFRS) kapsamında aşağıdaki stok değerleme yöntemlerinden hangisinin kullanımı yasaklanmıştır?', 'LIFO yöntemi', ['FIFO (İlk Giren İlk Çıkar) yöntemi', 'Ağırlıklı ortalama maliyet yöntemi', 'Gerçek parti maliyet yöntemi'], 'UFRS ve TFRS, bilançodaki stokların güncel değerden aşırı kopmasına yol açabildiği için LIFO yöntemini yasaklamıştır.'),
  ('Enflasyonist dönemde FIFO kullanan bir şirketin nakit akışı üzerinde vergi kaynaklı nasıl bir etki görülür?', 'Yüksek vergi nedeniyle nakit çıkışı artar', ['Düşük vergi nedeniyle nakit çıkışı azalır', 'Vergi tutarı stok yönteminden etkilenmez', 'Nakit akışı tamamen sıfır vergi avantajı sağlar'], 'FIFO yüksek muhasebe kârı (fiktif kâr dahil) raporladığından vergi yükü büyür ve nakit olarak daha fazla vergi ödenir.'),
  ('Faydalı ömrü 5 yıl olan 100.000 TL maliyetli bir makineye (hurda değer sıfır) çift azalan bakiyeler (%40 oran) uygulanırsa 2. yılın amortisman tutarı kaç TL olur?', '24.000 TL', ['40.000 TL olarak hesaplanır', '20.000 TL seviyesindedir', '36.000 TL düzeyindedir'], '1. yıl amortismanı 100.000 x %40 = 40.000 TL, kalan defter değeri 60.000 TL\'dir; 2. yıl amortismanı 60.000 x %40 = 24.000 TL olur.'),
  ('Amortisman giderinin işletmenin nakit akışı üzerindeki doğrudan etkisi aşağıdakilerden hangisidir?', 'Doğrudan nakit çıkışı yaratmaz', ['Kasa hesabından hemen para çıkışı doğurur', 'Banka kredisi anaparasını anında azaltır', 'Müşterilerden nakit tahsilatını hızlandırır'], 'Amortisman nakit çıkışı gerektirmeyen bir giderdir; ancak vergi matrahını düşürdüğü için dolaylı olarak vergi kalkanı (nakit tasarrufu) sağlar.'),
  ('Uluslararası Finansal Raporlama Standartlarına (UFRS/TFRS) göre satın alma yoluyla oluşan şerefiye sonraki dönemlerde nasıl muhasebeleştirilir?', 'Her yıl değer düşüklüğü testine tutulur', ['Sabit 5 yıllık sürede doğrusal itfa edilir', 'İlk yılın sonunda tamamen giderleştirilir', 'Her yıl enflasyon oranında otomatik artırılır'], 'UFRS/TFRS\'ye göre şerefiye sınırsız ömürlü kabul edilerek düzenli itfa edilmez; bunun yerine her yıl (veya gösterge oluştuğunda) değer düşüklüğü testinden geçirilir.'),
  ('Bir şirketin kendi iç bünyesinde yürüttüğü araştırma ve geliştirme (Ar-Ge) faaliyetlerinde hangi aşamanın harcamaları genel muhasebe standartlarında doğrudan dönem gideri yazılır?', 'Araştırma aşaması harcamaları', ['Ticari fizibilitesi kanıtlanmış geliştirme harcamaları', 'Satın alınmış patentlerin tescil bedelleri', 'Lisans sözleşmesiyle edinilen yazılım hakları'], 'Araştırma aşamasında gelecekteki ekonomik fayda kesin olmadığından bu harcamalar aktifleştirilemez, doğrudan giderleştirilir.'),
  ('Cari oranı 1,60 olan bir işletme, kasasındaki nakit ile vadesi gelmiş kısa vadeli tedarikçi borcunun bir kısmını öderse cari oranı nasıl değişir?', 'Artar', ['Azalır ve bire yaklaşır', 'Tam olarak aynı kalır', 'Sıfıra eşit hale gelir'], 'Cari oran 1\'den büyükken pay ve paydadan aynı tutarda eksiltme yapmak oranı büyütür (örneğin 160/100 = 1,60 iken 140/80 = 1,75 olur).'),
  ('Cari oranı 0,80 olan bir işletme, kısa vadeli borçlarından bir bölümünü nakit ödeyerek kapatırsa cari oran nasıl etkilenir?', 'Azalır', ['Artar ve birin üzerine çıkar', 'Değişmeden sabit kalır', 'Özkaynak oranı kadar yükselir'], 'Oran 1\'den küçükken pay ve paydadan eşit miktar çıkarıldığında oran küçülür (örneğin 80/100 = 0,80 iken 60/80 = 0,75 olur).'),
  ('Perakende devleri gibi bazı işletmelerin nakit dönüşüm süresinin negatif çıkması finansal açıdan ne anlama gelir?', 'Müşteriden parayı tedarikçiye ödemeden önce alır', ['İşletmenin sürekli nakit açığı içinde yüzdüğünü', 'Stokların depoda yıllarca satılmadan beklediğini', 'Müşterilere çok uzun vadeli satış yapıldığını'], 'Peşin satış yapıp tedarikçilere vadeli ödeme yapan işletmelerde nakit dönüşüm süresi negatif olur ve bu durum ücretsiz işletme finansmanı sağlar.'),
  ('Bir şirkette ticari alacak tahsil süresinin son üç yılda 30 günden 75 güne yükselmesi öncelikle hangi riski artırır?', 'Likidite sıkışıklığı ve tahsilat riskini', ['Üretim kapasitesinin aniden ikiye katlanmasını', 'Uzun vadeli duran varlıkların amortisman hızını', 'Özkaynak kârlılığının kendiliğinden artmasını'], 'Alacakların geç tahsil edilmesi nakit akışını yavaşlatır, işletme sermayesi ihtiyacını büyütür ve şüpheli alacak riskini artırır.'),
  ('Sabit maliyetleri değişmeyen bir işletmede hammadde zamları nedeniyle birim değişken maliyet artarsa başabaş noktası nasıl etkilenir?', 'Yükselir', ['Aynı seviyede sabit kalır', 'Hammadde zammı oranında düşer', 'Sıfır noktasına doğru geriler'], 'Birim değişken maliyetin artması birim katkı payını küçültür; sabit maliyetleri karşılamak için daha fazla ürün satılması gerekir, başabaş noktası yükselir.'),
  ('FAVÖK (EBITDA) göstergesinin tek başına serbest nakit akışı yerine kullanılmasının en önemli sakıncası aşağıdakilerden hangisidir?', 'Sermaye harcamalarını ve işletme sermayesini dışlaması', ['Amortisman giderlerini gereksiz yere iki kez çıkarması', 'Faaliyet kârını hesaba hiç dâhil etmemesi', 'Yalnızca banka kredisi olmayan şirketlerde hesaplanması'], 'FAVÖK nakit akışına yakınsasa da yenileme yatırımlarını (CapEx), vergi ödemelerini, faiz ödemelerini ve işletme sermayesi değişimini ihmal eder.'),
  ('DuPont analizinde özsermaye kârlılığı (ROE) %24 olan iki şirketten A\'nın net kâr marjı yüksek ve kaldıraç çarpanı düşük, B\'nin ise net kâr marjı düşük ve kaldıraç çarpanı çok yüksektir. Finansal risk açısından hangi değerlendirme doğrudur?', 'B şirketi daha yüksek finansal risk taşır', ['A şirketi daha yüksek borç temerrüt riski taşır', 'Her iki şirketin finansal riski tamamen aynıdır', 'B şirketinin operasyonel verimliliği daha üstündür'], 'Yüksek özsermaye çarpanı yüksek borçluluk anlamına gelir; B şirketi ROE\'yi kârlılıktan çok borç kaldıracıyla büyüttüğü için faiz ve iflas riski daha yüksektir.'),
  ('Aktif kârlılığı (ROA) %8 ve borç/özkaynak oranı 1,5 olan bir işletmenin DuPont ilişkisine göre özsermaye kârlılığı (ROE) yüzde kaçtır?', '%20', ['%12 olarak hesaplanır', '%16 seviyesindedir', '%24 düzeyindedir'], 'Borç/Özkaynak = 1,5 ise Varlık/Özkaynak (Özsermaye Çarpanı) = 1 + 1,5 = 2,5 olur; ROE = ROA x Özsermaye Çarpanı = %8 x 2,5 = %20\'dir.'),
  ('Genişletilmiş 5 faktörlü DuPont analizinde klasik 3 faktörlü modele ek olarak hangi iki unsur net kâr marjından ayrıştırılır?', 'Vergi yükü ve faiz yükü', ['Stok devir hızı ve cari oran', 'Amortisman oranı ve kira gideri', 'Temettü dağıtım ve büyüme oranı'], '5 faktörlü DuPont modeli net kâr marjını faaliyet kâr marjı, faiz yükü (VÖK/FVÖK) ve vergi yükü (Net Kâr/VÖK) olarak üç alt bileşene ayırır.'),
  ('Faiz oranlarının hızla yükseldiği bir ekonomide çok yüksek finansal kaldıraçla çalışan bir işletmenin karşılaşacağı en kritik tehlike nedir?', 'Faiz yükü nedeniyle negatif kaldıraç ve zarar', ['Özsermaye kârlılığının otomatik olarak artması', 'Dönen varlıkların kendiliğinden nakde dönmesi', 'Sabit üretim maliyetlerinin sıfırlanması'], 'Borçlanma maliyeti aktif getirisinin üzerine çıktığında finansal kaldıraç tersine işler, artan faiz giderleri kârı eritir ve özkaynağı aşındırır.'),
  ('Bir bankanın kredi değerlendirme komitesi, faiz karşılama oranı 0,85 olan bir şirketin kredi başvurusunu incelerken hangi temel sonuca ulaşır?', 'Faaliyet kârı mevcut faizleri bile karşılamıyor', ['Şirket faiz giderlerini fazlasıyla ödeyebiliyor', 'Şirketin hiç finansal borcu bulunmamaktadır', 'Net kâr marjı sektör ortalamasının üstündedir'], 'Faiz karşılama oranının 1\'in altında olması, şirketin esas faaliyetlerinden kazandığı kârın mevcut borç faizlerini ödemeye dahi yetmediğini gösterir.'),
  ('Toplam finansal borcu 900.000 TL, nakit ve nakit benzerleri 180.000 TL ve yıllık FAVÖK tutarı 240.000 TL olan bir işletmenin Net Borç / FAVÖK oranı kaçtır?', '3,0', ['3,75 olarak hesaplanır', '4,50 seviyesindedir', '2,25 düzeyindedir'], 'Önce Net Borç = 900.000 - 180.000 = 720.000 TL bulunur; ardından Net Borç / FAVÖK = 720.000 / 240.000 = 3,0 elde edilir.'),
  ('Dolaylı yöntemle işletme faaliyetlerinden nakit akışı hesaplanırken dönem içinde ticari alacakların artması nakit akışını nasıl etkiler?', 'Nakit akışını azaltıcı unsur olarak düşülür', ['Nakit akışını artırıcı unsur olarak eklenir', 'Nakit akışı üzerinde hiçbir etki yaratmaz', 'Sadece yatırım faaliyetleri bölümüne yazılır'], 'Ticari alacakların artması, gelir tablosuna yazılan satışların henüz tahsil edilmediğini gösterir; bu yüzden net kârdan düşülerek nakit akışına ulaşılır.'),
  ('Dönem içinde tedarikçilere olan ticari borçların artması işletme faaliyetlerinden nakit akışını nasıl etkiler?', 'Nakit çıkışı ertelendiği için pozitif etkiler', ['Kasadan nakit çıktığı için negatif etkiler', 'Finansman faaliyetlerinde nakit çıkışı sayılır', 'Nakit akışı hesaplamasında dikkate alınmaz'], 'Ticari borçların artması, gider veya stok alımı için henüz nakit ödenmediğini ifade ettiğinden dönem içi nakdin işletmede kalmasını sağlar.'),
  ('Gelir tablosunda sürekli yüksek net kâr açıklayan ancak işletme faaliyetlerinden nakit akışı üst üste üç yıl negatif çıkan bir şirket için en gerçekçi uyarı nedir?', 'Kârın nakde dönüşmediği ve likidite riski doğduğu', ['Şirketin çok sağlıklı biçimde nakit biriktirdiği', 'Amortisman giderlerinin sıfıra indirilmiş olduğu', 'Borç ödeme kapasitesinin sınırsız biçimde arttığı'], 'Kârın tahsil edilemeyen alacaklarda veya satılamayan stoklarda birikmesi kâr kalitesinin düşük olduğuna ve nakit krizine işaret eder.'),
  ('Faaliyet kaldıracı derecesi 4 olan bir işletmede satış hacmi %5 oranında azalırsa esas faaliyet kârında (FVÖK) yüzde kaçlık bir düşüş beklenir?', '%20', ['%5 olarak hesaplanır', '%1,25 seviyesindedir', '%9 düzeyindedir'], 'FVÖK\'teki yüzdesel değişim = Faaliyet Kaldıracı Derecesi x Satışlardaki Yüzdesel Değişim = 4 x (-%5) = -%20 olur.'),
  ('Sabit maliyetleri 150.000 TL, birim satış fiyatı 80 TL ve birim değişken maliyeti 50 TL olan bir işletme 60.000 TL hedef faaliyet kârı elde etmek için kaç adet ürün satmalıdır?', '7.000 adet', ['5.000 adet olarak hesaplanır', '2.000 adet seviyesindedir', '6.500 adet düzeyindedir'], 'Hedef Satış Miktarı = (Sabit Maliyet + Hedef Kâr) / Birim Katkı Payı = (150.000 + 60.000) / (80 - 50) = 210.000 / 30 = 7.000 adettir.'),
  ('Bir şirketin PD/DD oranının uzun süre 1,0\'ın belirgin biçimde altında seyretmesi piyasa açısından hangi temel beklentiye işaret edebilir?', 'Gelecekte düşük özsermaye kârlılığı veya varlık riski', ['Şirketin sınırsız yüksek kâr büyümesi beklediği', 'Özkaynakların tamamının nakit kasada tutulduğu', 'Hisse fiyatının defter değerinin çok üzerinde olduğu'], 'PD/DD\'nin 1\'in altında kalması, piyasanın şirketin özkaynak maliyetini karşılayacak düzeyde ROE üretemeyeceğini ya da varlıkların aşırı değerlendiğini düşündüğünü gösterir.'),
  ('Hukuki biçimi kira sözleşmesi olan uzun vadeli bir finansal kiralama (leasing) işleminin, ekonomik gerçekliği nedeniyle bilançoda varlık ve borç olarak gösterilmesi hangi ilkenin sonucudur?', 'Özün önceliği kavramı', ['Maliyet esası kavramı', 'Parayla ölçülme kavramı', 'Dönemsellik kavramı ilkesi'], 'Özün önceliği ilkesi, işlemlerin yalnızca hukuki şekline değil finansal ve ekonomik özüne göre muhasebeleştirilmesini gerektirir.'),
  ('1 Ekim tarihinde 1 yıllık (12 aylık) kira bedeli olarak 120.000 TL peşin ödeyen bir işletme, 31 Aralık yıl sonu kapanışında gelir tablosuna kaç TL kira gideri yazmalıdır?', '30.000 TL', ['120.000 TL olarak kaydedilir', '90.000 TL seviyesindedir', '40.000 TL düzeyindedir'], 'Aylık kira 120.000 / 12 = 10.000 TL\'dir; Ekim, Kasım ve Aralık (3 ay) bu yıla ait olduğundan 30.000 TL gider yazılır, kalan 90.000 TL aktifte bekler.'),
  ('Bir şirketin stok değerlemesinde net gerçekleşebilir değer (satış fiyatı eksi tamamlama/satış gideri), stokun maliyetinin altına düşerse uluslararası standartlara göre stok bilançoda hangi değerle gösterilir?', 'Maliyet ve net gerçekleşebilir değerden düşük olanıyla', ['Her zaman ilk satın alma maliyetiyle sabit olarak', 'Sadece brüt satış fiyatının iki katı üzerinden', 'Dönem sonunda sıfır değer üzerinden silinerek'], 'Stoklar "maliyet ile net gerçekleşebilir değerden düşük olanı" ilkesiyle değerlenir ve değer düşüklüğü derhal giderleştirilir.'),
  ('Maliyeti 300.000 TL ve birikmiş amortismanı 180.000 TL olan bir kamyonet 145.000 TL\'ye satılmıştır. Bu satıştan elde edilen muhasebe kârı veya zararı nedir?', '25.000 TL kâr', ['155.000 TL zarar olarak bulunur', '35.000 TL zarar seviyesindedir', '145.000 TL kâr düzeyindedir'], 'Net defter değeri = 300.000 - 180.000 = 120.000 TL\'dir; 145.000 TL\'ye satıldığı için 145.000 - 120.000 = 25.000 TL satış kârı oluşur.'),
  ('Bir şirket kısa vadeli banka kredisi çekerek elde ettiği nakdi kasasında tutarsa net işletme sermayesi ve cari oranı (başlangıçta cari oran 1,50 iken) nasıl değişir?', 'Net işletme sermayesi değişmez, cari oran düşer', ['Hem net işletme sermayesi hem cari oran artar', 'Net işletme sermayesi artar, cari oran sabit kalır', 'Hem net işletme sermayesi hem cari oran yükselir'], 'Dönen varlıklar ve kısa vadeli borçlar aynı tutarda arttığı için fark (NİS) değişmez; başlangıçta oran 1\'den büyük olduğundan pay ve paydaya eşit ekleme cari oranı küçültür.'),
  ('Aynı sektörde faaliyet gösteren iki şirketten X\'in brüt kâr marjı %22, Y\'nin brüt kâr marjı %38 ise Y şirketinin bu üstünlüğü aşağıdakilerden hangisiyle doğrudan açıklanamaz?', 'Y\'nin daha düşük kurumlar vergisi ödemesiyle', ['Y\'nin marka gücüyle daha yüksek fiyatlamasıyla', 'Y\'nin ölçek ekonomisiyle ucuza hammadde almasıyla', 'Y\'nin üretim süreçlerinde daha az fire vermesiyle'], 'Kurumlar vergisi gelir tablosunun en altında (net kâr aşamasında) yer alır; dolayısıyla brüt kâr marjını etkilemez.'),
  ('Yüksek enflasyon dönemlerinde enflasyon düzeltmesi yapılmamış geleneksel mali tablolar üzerinden yapılan finansal analizde en tipik bozulma aşağıdakilerden hangisidir?', 'Düşük tarihi amortisman nedeniyle kârın şişkin görünmesi', ['Duran varlıkların piyasa değerinden çok yüksek görünmesi', 'Satış gelirlerinin her yıl gerçek değerinden düşük çıkması', 'Borç oranının enflasyon arttıkça sıfıra düşmesi'], 'Tarihi maliyetle kayıtlı eski makinelerin amortismanı güncel fiyatlara göre çok küçük kaldığından giderler düşük, muhasebe kârı ise yapay olarak şişkin görünür.'),
  ('Bağımsız dış denetim raporunda denetçinin "olumlu (şartsız) görüş" vermesi, finansal tablo kullanıcılarına hangi güvenceyi sağlar?', 'Tabloların standartlara uygun ve gerçeğe dürüst sunulduğunu', ['Şirketin gelecek beş yıl boyunca kesin kâr edeceğini', 'Hisse senedi fiyatının borsada kesinlikle yükseleceğini', 'Şirkette tek bir kuruş dahi küçük hata bulunmadığını'], 'Olumlu denetim görüşü gelecekteki kârlılığı garanti etmez; finansal tabloların muhasebe standartlarına uygun biçimde ve önemli yanlışlık içermeden hazırlandığına makul güvence verir.'),
];
